<script setup lang="ts">
import type { BsCommitmentActionForm, BsOperationalRecordsCopy, BsOperationalRecordsView, BsOperationalRecordsJournalForm } from '../types/operationalRecordsPresentation'
defineProps<{ copy: BsOperationalRecordsCopy; view: BsOperationalRecordsView }>()
const commitment = defineModel<BsCommitmentActionForm>('commitment', { required: true })
const journal = defineModel<BsOperationalRecordsJournalForm>('journal', { required: true })
const emit = defineEmits<{ create: []; retry: []; openJournal: [id: string]; commitment: [id: string, mode: 'settle' | 'postpone']; cancelCommitment: [id: string]; ruleStatus: [id: string, status: 'active' | 'paused']; closeCommitment: []; submitCommitment: []; closeJournal: []; retryJournal: []; retryTags: []; assignTag: []; removeTag: [id: string]; upload: [event: Event]; download: [id: string]; deleteAttachment: [id: string]; reverse: [] }>()
function field<K extends keyof BsCommitmentActionForm>(key: K, value: BsCommitmentActionForm[K]) { commitment.value = { ...commitment.value, [key]: value } }
</script>
<template>
  <BsStack gap="lg">
    <BsPageHeader :title="copy.title" :subtitle="copy.count"><template #actions><BsLink v-if="view.kind === 'journals'" :to="view.journalDirectoryTo">{{ copy.allJournals }}</BsLink><BsButton v-if="view.canCreate" variant="primary" @click="emit('create')">{{ copy.create }}</BsButton></template></BsPageHeader>
    <BsCard v-if="view.guide" as="section" padding="lg"><BsStack gap="md"><BsHeading :level="2" size="h3">{{ view.guide.title }}</BsHeading><BsText tone="muted">{{ view.guide.body }}</BsText><BsGrid :columns="3" gap="md"><BsBox v-for="step in view.guide.steps" :key="step.id" padding="lg" surface="muted" radius="control"><BsHeading :level="3" size="body">{{ step.title }}</BsHeading><BsText size="sm" tone="muted">{{ step.body }}</BsText></BsBox></BsGrid><BsText size="sm" tone="muted">{{ view.guide.example }}</BsText><BsLink v-if="view.guide.link" :to="view.guide.link">{{ view.guide.linkLabel }}<BsIcon name="arrowRight" directional :size="18"/></BsLink></BsStack></BsCard>
    <BsStateSurface v-if="view.failed" state="error" :title="copy.failed" :action-label="copy.retry" @action="emit('retry')"/><BsSectionSkeleton v-else-if="view.loading" variant="table" :rows="8"/><BsEmptyState v-else-if="!view.rows.length" :title="copy.empty" :description="copy.emptyHint" :action-label="view.canCreate ? copy.create : undefined" @action="emit('create')"/>
    <BsCard v-else padding="none">
      <BsDataTable v-if="view.kind === 'journals'" :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'date', field: 'date', header: copy.date }, { key: 'name', field: 'name', header: copy.description }, { key: 'category', field: 'category', header: copy.category }, { key: 'accounts', header: copy.fromTo }, { key: 'status', header: copy.status }, { key: 'amount', field: 'amount', header: copy.amount, align: 'end' }]" @row-click="event => emit('openJournal', event.data.id)"><template #cell-accounts="{ row }">{{ row.from }} <BsIcon name="arrowRight" :size="14" directional/> {{ row.to }}</template><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template></BsDataTable>
      <BsDataTable v-else-if="view.kind === 'commitments'" :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'name', field: 'name', header: copy.name }, { key: 'kind', field: 'kind', header: copy.kind }, { key: 'date', field: 'date', header: copy.date }, { key: 'status', header: copy.status }, { key: 'amount', field: 'amount', header: copy.amount, align: 'end' }, { key: 'actions', header: copy.actions, align: 'end' }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template><template #cell-actions="{ row }"><BsInline><BsButton v-if="row.canSettle" size="sm" @click="emit('commitment', row.id, 'settle')">{{ copy.settle }}</BsButton><BsButton v-if="row.canPostpone" size="sm" @click="emit('commitment', row.id, 'postpone')">{{ copy.postpone }}</BsButton><BsButton v-if="row.canCancel" :disabled="view.pending" size="sm" @click="emit('cancelCommitment', row.id)">{{ copy.cancel }}</BsButton></BsInline></template></BsDataTable>
      <BsDataTable v-else-if="view.kind === 'recurring'" :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'name', field: 'name', header: copy.name }, { key: 'kind', field: 'kind', header: copy.kind }, { key: 'schedule', field: 'schedule', header: copy.schedule }, { key: 'nextRun', field: 'nextRun', header: copy.nextRun }, { key: 'status', header: copy.status }, { key: 'actions', header: copy.actions, align: 'end' }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template><template #cell-actions="{ row }"><BsInline><BsButton v-if="row.canPause" :disabled="view.pending" size="sm" @click="emit('ruleStatus', row.id, 'paused')">{{ copy.pause }}</BsButton><BsButton v-if="row.canResume" :disabled="view.pending" size="sm" @click="emit('ruleStatus', row.id, 'active')">{{ copy.resume }}</BsButton></BsInline></template></BsDataTable>
      <BsDataTable v-else-if="view.kind === 'parties'" :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'name', field: 'name', header: copy.name }, { key: 'kind', field: 'kind', header: copy.kind }, { key: 'email', field: 'email', header: copy.email }, { key: 'phone', field: 'phone', header: copy.phone }, { key: 'status', header: copy.status }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template></BsDataTable>
      <BsDataTable v-else-if="view.kind === 'tags'" :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'name', header: copy.name }, { key: 'date', field: 'date', header: copy.created }, { key: 'actions', header: copy.actions, align: 'end', hidden: !view.rows.some(row => row.toJournal) }]"><template #cell-name="{ row }"><BsInline as="span" gap="sm"><BsColorSwatch :color="row.color"/>{{ row.name }}</BsInline></template><template #cell-actions="{ row }"><BsLink v-if="row.toJournal" :to="row.toJournal">{{ copy.viewJournals }}</BsLink></template></BsDataTable>
      <BsDataTable v-else :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'email', field: 'email', header: copy.email }, { key: 'role', field: 'role', header: copy.role }, { key: 'status', header: copy.status }, { key: 'date', field: 'date', header: copy.created }, { key: 'expires', field: 'expires', header: copy.expires }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template></BsDataTable>
    </BsCard><BsText v-if="view.error && !view.dialog.visible" role="alert" tone="danger">{{ view.error }}</BsText>
    <BsRecordActionDialog :visible="view.dialog.visible" :title="view.dialog.title" size="md" :dirty="view.dialog.dirty" :pending="view.dialog.pending" :error="view.dialog.error" :submit-label="view.dialog.submit" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('closeCommitment') }" @submit="emit('submitCommitment')"><template v-if="view.dialog.settling"><BsFloatingField :label="copy.account"><BsSelect :model-value="commitment.account" :label="copy.account" :options="[{ value: '', label: copy.account }, ...view.dialog.accounts]" option-label="label" option-value="value" native required @update:model-value="field('account', String($event))"/></BsFloatingField><BsFloatingField :label="copy.partialAmount"><BsInput :model-value="commitment.amount" inputmode="decimal" :placeholder="copy.partialAmount" @update:model-value="field('amount', String($event ?? ''))"/></BsFloatingField></template><BsFloatingField :label="copy.actionDate"><BsInput :model-value="commitment.date" type="date" required @update:model-value="field('date', String($event ?? ''))"/></BsFloatingField></BsRecordActionDialog>
    <BsJournalDetailDialog v-model:form="journal" :copy="view.journal.copy" :view="view.journal.view" @close="emit('closeJournal')" @retry="emit('retryJournal')" @retry-tags="emit('retryTags')" @assign-tag="emit('assignTag')" @remove-tag="emit('removeTag', $event)" @upload="emit('upload', $event)" @download="emit('download', $event)" @delete="emit('deleteAttachment', $event)" @navigate="emit('openJournal', $event)" @reverse="emit('reverse')"/>
  </BsStack>
</template>
